source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # The five-cell horizontal sample is the pattern to copy.
    template = None
    for r, row in enumerate(grid):
        for c in range(w - 4):
            vals = row[c:c + 5]
            if all(v != bg for v in vals):
                template = (r, c, vals[:])
                break
        if template is not None:
            break
    if template is None:
        return [row[:] for row in grid]
    tr, tc, pattern = template

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            # Every isolated non-background cell outside the sample is a stamp marker.
            if (r, c) == (tr, tc):
                continue
            if grid[r][c] != bg:
                if tr == r and tc <= c < tc + 5:
                    continue
                left = c - 2
                for k, val in enumerate(pattern):
                    if 0 <= left + k < w:
                        out[r][left + k] = val
    return out
